x-code-samples.source:
sdk.abac.rules.create({
    tags: [
        `${TAGS_ARR_STR}`
    ],
    action: `${ACTION_STR}`,
    resource: `${RESOURCE_STR}`,
    relatedResource: `${RELATED_RESOURCE_STR}`,
    team: `${TEAM_STR}`
})

sdk.accounts.updateAccountPublicSettings({ accountId }, {
    integrations: { ...INTEGRATIONS_OBJ },
    notifications: [
        {
            events: [
                `${EVENTS_ARR_STR}`
            ],
            slack: {
                uri: `${URI_STR}`
            },
            type: `${TYPE_STR}`,
            webhook: {
                method: `${METHOD_STR}`,
                uri: `${URI_STR}`
            }
        }
    ]
})

sdk.accounts.updateUserDetails({ accountId, userId }, {
    logins: { ...LOGINS_OBJ },
    key: { ...KEY_OBJ },
    settings: { ...SETTINGS_OBJ }
})

sdk.accounts.setSegment({ accountId, segmentType }, {
    trial: {
        trialing: TRIALING_BOOL,
        trialWillEndNotified: TRIAL_WILL_END_NOTIFIED_BOOL,
        trialEndedNotified: TRIAL_ENDED_NOTIFIED_BOOL,
        type: `${TYPE_STR}`,
        previousSegment: `${PREVIOUS_SEGMENT_STR}`,
        trialEnd: `${TRIAL_END_STR}`,
        trialStart: `${TRIAL_START_STR}`
    }
})

sdk.annotations.createMany({
    annotations: {
        set: [
            {
                entityId: `${ENTITY_ID_STR}`,
                entityType: `${ENTITY_TYPE_STR}`,
                annotations: [
                    { ...ANNOTATIONS_ARR_OBJ }
                ],
                display: `${DISPLAY_STR}`
            }
        ],
        unset: [
            {
                entityId: `${ENTITY_ID_STR}`,
                entityType: `${ENTITY_TYPE_STR}`,
                annotations: [
                    { ...ANNOTATIONS_ARR_OBJ }
                ]
            }
        ]
    }
})

sdk.compositions.create({
    isAdvanced: IS_ADVANCED_BOOL,
    name: `${NAME_STR}`,
    vars: [
        `${VARS_ARR_STR}`
    ],
    yamlJson: `${YAML_JSON_STR}`
})

sdk.compositions.update({ id }, {
    isAdvanced: IS_ADVANCED_BOOL,
    name: `${NAME_STR}`,
    vars: [
        `${VARS_ARR_STR}`
    ],
    yamlJson: `${YAML_JSON_STR}`
})

sdk.triggers.events.create({ public, pipeline }, {
    type: `${TYPE_STR}`,
    kind: `${KIND_STR}`,
    filter: `${FILTER_STR}`,
    secret: `${SECRET_STR}`,
    values: {
        namespace: `${NAMESPACE_STR}`,
        name: `${NAME_STR}`,
        action: `${ACTION_STR}`
    }
})

sdk.images.upsertMetadata({ dockerImageId }, {
    CF_QUALITY: CF_QUALITY_BOOL,
    comment: `${COMMENT_STR}`,
    coverage: `${COVERAGE_STR}`,
    failed_tests: FAILED_TESTS_NUM
})

sdk.helm.charts.install.new({ selector, tillerNamespace }, {
    name: `${NAME_STR}`,
    namespace: `${NAMESPACE_STR}`,
    releaseName: `${RELEASE_NAME_STR}`,
    set: [
        {
            key: `${KEY_STR}`,
            value: `${VALUE_STR}`
        }
    ],
    values: [
        {
            name: `${NAME_STR}`
        }
    ],
    repository: `${REPOSITORY_STR}`,
    version: `${VERSION_STR}`
})

sdk.helm.charts.install({ selector, tillerNamespace }, {
    name: `${NAME_STR}`,
    namespace: `${NAMESPACE_STR}`,
    releaseName: `${RELEASE_NAME_STR}`,
    set: [
        {
            key: `${KEY_STR}`,
            value: `${VALUE_STR}`
        }
    ],
    values: [
        {
            name: `${NAME_STR}`
        }
    ],
    repository: `${REPOSITORY_STR}`,
    version: `${VERSION_STR}`
})

sdk.helm.charts.promote.new({ selector, tillerNamespace }, {
    targetTillerNamespace: `${TARGET_TILLER_NAMESPACE_STR}`,
    targetNamespace: `${TARGET_NAMESPACE_STR}`,
    releaseName: `${RELEASE_NAME_STR}`,
    targetReleaseName: `${TARGET_RELEASE_NAME_STR}`,
    set: [
        {
            key: `${KEY_STR}`,
            value: `${VALUE_STR}`
        }
    ],
    values: [
        {
            name: `${NAME_STR}`
        }
    ],
    targetSelector: `${TARGET_SELECTOR_STR}`,
    revision: `${REVISION_STR}`,
    pipelineId: `${PIPELINE_ID_STR}`
})

sdk.pipelines.runYaml({ reqId }, {
    previousWorkflow: {
        id: `${ID_STR}`
    },
    branch: `${BRANCH_STR}`,
    trigger: `${TRIGGER_STR}`,
    variables: { ...VARIABLES_OBJ },
    options: {
        noCache: NO_CACHE_BOOL,
        noCfCache: NO_CF_CACHE_BOOL,
        resetVolume: RESET_VOLUME_BOOL,
        enableNotifications: ENABLE_NOTIFICATIONS_BOOL
    }
})

sdk.pipelines.run({ reqId, name }, {
    branch: `${BRANCH_STR}`,
    trigger: `${TRIGGER_STR}`,
    variables: { ...VARIABLES_OBJ },
    options: {
        noCache: NO_CACHE_BOOL,
        noCfCache: NO_CF_CACHE_BOOL,
        resetVolume: RESET_VOLUME_BOOL,
        enableNotifications: ENABLE_NOTIFICATIONS_BOOL
    }
})

sdk.pipelines.debug({ reqId, name }, {
    branch: `${BRANCH_STR}`,
    trigger: `${TRIGGER_STR}`,
    variables: { ...VARIABLES_OBJ },
    options: {
        noCache: NO_CACHE_BOOL,
        noCfCache: NO_CF_CACHE_BOOL,
        resetVolume: RESET_VOLUME_BOOL,
        enableNotifications: ENABLE_NOTIFICATIONS_BOOL
    }
})

sdk.pipelines.createPipelineFromTemplate({ name }, {
    name: `${NAME_STR}`,
    project: `${PROJECT_STR}`,
    description: `${DESCRIPTION_STR}`,
    isTemplate: IS_TEMPLATE_BOOL
})

sdk.pipelines.replace({ name, skipTriggerValidation, disableRevisionCheck }, {
    kind: `${KIND_STR}`,
    metadata: {
        name: `${NAME_STR}`
    },
    spec: {
        variables: [
            {
                key: `${KEY_STR}`,
                value: `${VALUE_STR}`
            }
        ],
        triggers: [
            {
                type: `${TYPE_STR}`
            }
        ]
    }
})

sdk.steps.list({
    id,
    official,
    freeText,
    category,
    tag,
    public,
    private,
    stage,
    offset,
    limit
})

sdk.steps.replace({ name }, {
    kind: `${KIND_STR}`,
    metadata: {
        name: `${NAME_STR}`
    },
    spec: { ...SPEC_OBJ }
})

sdk.environments-v2.replace({ name }, {
    kind: `${KIND_STR}`,
    metadata: {
        name: `${NAME_STR}`
    },
    spec: { ...SPEC_OBJ }
})

sdk.environments-v2.update({ name }, {
    kind: `${KIND_STR}`,
    metadata: {
        name: `${NAME_STR}`
    },
    spec: { ...SPEC_OBJ }
})

sdk.environments-v2.reset.new({ name }, {
    kind: `${KIND_STR}`,
    metadata: {
        name: `${NAME_STR}`
    },
    spec: { ...SPEC_OBJ }
})

sdk.environments-v2.argo.rollback({ name }, {
    deploymentId: DEPLOYMENT_ID_NUM,
    contextName: `${CONTEXT_NAME_STR}`,
    applicationName: `${APPLICATION_NAME_STR}`
})

sdk.gitops-application.replace({ name }, {
    kind: `${KIND_STR}`,
    metadata: {
        name: `${NAME_STR}`
    },
    spec: { ...SPEC_OBJ }
})

sdk.gitops-application.update({ name }, {
    kind: `${KIND_STR}`,
    metadata: {
        name: `${NAME_STR}`
    },
    spec: { ...SPEC_OBJ }
})

sdk.argo-runtime.setCsdpSettings({
    force: FORCE_BOOL,
    gitProvider: `${GIT_PROVIDER_STR}`,
    gitApiUrl: `${GIT_API_URL_STR}`,
    sharedConfigRepo: `${SHARED_CONFIG_REPO_STR}`
})

sdk.projects.create({
    projectName: `${PROJECT_NAME_STR}`,
    tags: [
        `${TAGS_ARR_STR}`
    ],
    variables: [
        {
            key: `${KEY_STR}`,
            value: `${VALUE_STR}`
        }
    ]
})

sdk.repos.create({ context }, {
    serviceDetails: {
        name: `${NAME_STR}`,
        scm: {
            name: `${NAME_STR}`,
            owner: {
                name: `${NAME_STR}`
            }
        }
    }
})
